tool_input.command:
python3 - <<'EOF'
p='src/Storefront/Invoices/Money.cs'
s=open(p,encoding='utf-8').read()
old='''    private static readonly CultureInfo StoreCulture = CultureInfo.GetCultureInfo("de-DE");
'''
new='''    // Spelled out rather than read from the "de-DE" culture: culture data comes from the host's ICU,
    // and a host without it (invariant globalization) silently falls back to "1,234.50".
    private static readonly NumberFormatInfo StoreFormat = new()
    {
        NumberGroupSeparator = ".",
        NumberDecimalSeparator = ",",
        NumberGroupSizes = [3],
    };
'''
assert old in s
s=s.replace(old,new).replace('amount.ToString("N2", StoreCulture)','amount.ToString("N2", StoreFormat)')
open(p,'w',encoding='utf-8').write(s)
EOF
git diff --stat && dotnet test 2>&1 | tail -15 && DOTNET_SYSTEM_GLOBALIZATION_INVARIANT=1 DOTNET_SYSTEM_GLOBALIZATION_PREDEFINED_CULTURES_ONLY=false dotnet test --no-build --filter "FullyQualifiedName~MoneyTests|FullyQualifiedName~ReceiptTests" 2>&1 | tail -8
